const req = $('Payment Creation Webhook').first().json.body;
const user = $json || {};

const cpf = req.passenger_cpf || req.documents?.["1"] || user.cpf || "00000000000";
const name = req.passenger_name || req.name || req.customers?.["1"] || user.full_name || "Passageiro";
const phone = user.phone_number || req.phone || "5593999999999";

let reqPrice = 0;
let reqTax = "0.0";
if (req.data) {
  try {
    const dataObj = typeof req.data === 'string' ? JSON.parse(req.data) : req.data;
    const item = Array.isArray(dataObj) ? dataObj[0] : dataObj;
    if (item) {
      reqPrice = Number(item.price ?? 0);
      reqTax = String(item.tax ?? "0.0");
    }
  } catch (e) {}
}

const price = Number(req.price || reqPrice || 0);
const tax = String(req.tax ?? reqTax ?? "0.0");
const seatNumber = req.seat_number || (Array.isArray(req.seat_numbers) ? req.seat_numbers[0] : null);

const dataArray = [{
  comodity: "Assento",
  field: "speed_boat_price",
  customer_fields: 1,
  min_customer_fields: 1,
  price: price,
  tax: tax,
  quantity: 1
}];

const routeId = req.route_id && req.route_id !== "route_id_placeholder" ? req.route_id : (user.state_payload?.route_id || req.route_id);
const tripId = req.trip_id && req.trip_id !== "trip_id_placeholder" ? req.trip_id : (user.state_payload?.trip_id || req.trip_id);
const travelDate = req.date && req.date !== "date_placeholder" ? req.date : (user.state_payload?.travel_date || req.date);

const order = {
  route_id: routeId,
  trip_id: tripId,
  date: travelDate,
  payment_method: req.payment_method || "PIX",
  name: name,
  phone: phone,
  customers: { "1": name },
  documents: { "1": String(cpf).replace(/\D/g, "") },
  document_types: { "1": "cpf" },
  birthdays: [req.passenger_birthday || (Array.isArray(req.birthdays) ? req.birthdays[0] : "1990-01-01")],
  seat_numbers: seatNumber ? [Number(seatNumber)] : [],
  return_seat_numbers: [],
  data: JSON.stringify(dataArray)
};

return [{ json: { session_id: user.id || req.session_id || null, phone_number: phone, order, original_req: req, seat_number: seatNumber } }];
